export function Comment({
  author = "{{author}}",
  initials = "{{initials}}",
  body = "{{body}}",
  timestamp = "{{timestamp}}",
  accent = "{{accent}}",
  edited = {{edited}},
}) {
  return (
    <article style={{ display: "flex", gap: 12, maxWidth: 420, fontFamily: "system-ui, sans-serif", fontSize: 14, lineHeight: 1.5, color: "#241430" }}>
      <span style={{ width: 36, height: 36, borderRadius: "50%", flexShrink: 0, display: "grid", placeItems: "center", background: accent, color: "#FAF7F2", fontSize: 12, fontWeight: 700 }} aria-hidden="true">{initials}</span>
      <div style={{ flex: 1, minWidth: 0 }}>
        <header style={{ display: "flex", alignItems: "baseline", gap: 8, flexWrap: "wrap" }}>
          <span style={{ fontWeight: 600 }}>{author}</span>
          <time style={{ fontSize: 12, color: "#24143080" }} dateTime="2026-08-18T09:00">{timestamp}</time>
          {edited && <span style={{ fontSize: 12, color: "#24143080", fontStyle: "italic" }}>(edited)</span>}
        </header>
        <p style={{ margin: "6px 0 0" }}>{body}</p>
      </div>
    </article>
  );
}
